%[text] # BEV Controller - Simulation Case
%[text] ## Simple
model_name = "HarnessModel_BEVController";
load_system(model_name) 

BEVController_Basic_params

set_param(model_name + "/BEV Speed Tracking Controller", ReferencedSubsystem = "BEVController_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_BEVController_Simple_refsub");
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "600");

sim_out = sim(sim_in);

simResultTimetable = extractTimetable(sim_out.logsout);
%[text] 
fig = figure; %[output:45a5e1a1]
hold on %[output:45a5e1a1]
grid on %[output:45a5e1a1]
axis padded %[output:45a5e1a1]
fig.Position(3:4) = [700 300];  % width height %[output:45a5e1a1]

plot(simResultTimetable, "Time", "Vehicle speed input kph", LineWidth=2) %[output:45a5e1a1]
title("Input to controller: Vehicle target speed") %[output:45a5e1a1]
ylabel("km/h") %[output:45a5e1a1]
fig = figure; %[output:8e6b51bf]
hold on %[output:8e6b51bf]
grid on %[output:8e6b51bf]
axis padded %[output:8e6b51bf]
fig.Position(3:4) = [700 300];  % width height %[output:8e6b51bf]

plot(simResultTimetable, "Time", "Motor torque command", LineWidth=2) %[output:8e6b51bf]
title("Output from controller: Motor torque command") %[output:8e6b51bf]
ylabel("N*m") %[output:8e6b51bf]
